import styled from '@emotion/styled';

export const StyledPortfolioBigNumberCardRoot = styled.div({
  width: '100%',
  minWidth: 0,
  maxWidth: '100%',
  boxSizing: 'border-box',
  height: '100%',
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
});

export const StyledPortfolioBigNumberCardBody = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  width: '100%',
  minWidth: 0,
  flex: '1 1 auto',
});

export const StyledPortfolioKpiBigNumberShell = styled.div({
  width: '100%',
  minWidth: 0,
  flex: '1 1 auto',
  display: 'flex',
  padding: '20px',
  flexDirection: 'column',
  gap: '16px',
  minHeight: 0,
  border: '1px solid #e8e8e8',
  borderRadius: '12px',
  background: '#FFFFFF',
  overflow: 'hidden',
  boxShadow: 'none',

  '& .innovation-hub-portfolio-big-number-card.bigNumberContainer': {
    padding: '0',
    gap: '10px',
    height: 'auto',
  },

  '& .innovation-hub-portfolio-big-number-card': {
    width: '100%',
    maxWidth: '100%',
    minWidth: 0,
    gap: '4px',

    '& h1': {
      maxWidth: '100%',
      minWidth: 0,
      whiteSpace: 'nowrap',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
    },
  },

  '& [data-testid$="-chart-header-measure"]': {
    fontSize: '14px !important',
    lineHeight: '1.4',
    fontWeight: 400,
  },
});

export const StyledPortfolioChartHeaderAlignStart = styled.div({
  width: '100%',
  minWidth: 0,
  alignSelf: 'stretch',
  boxSizing: 'border-box',

  '& [data-testid$="-chart-header-content"] > div:first-of-type': {
    alignItems: 'flex-start !important',
  },

  '& [data-testid$="-chart-header-title"]': {
    textAlign: 'left',
  },

  '& [data-testid$="-chart-header-measure"]': {
    textAlign: 'left',
  },
});
